create table if not exists public.platform_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  email text not null unique,
  role text not null default 'super_admin' check (role in ('super_admin','platform_support')),
  status text not null default 'active' check (status in ('active','suspended')),
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id) on delete set null
);

alter table public.schools add column if not exists approval_status text not null default 'pending' check (approval_status in ('pending','approved','rejected','suspended'));
alter table public.schools add column if not exists approved_at timestamptz;
alter table public.schools add column if not exists approved_by uuid references auth.users(id) on delete set null;
alter table public.schools add column if not exists rejection_reason text;

create index if not exists schools_approval_status_idx on public.schools (approval_status, created_at desc);

create or replace function public.is_platform_admin() returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.platform_admins where user_id = auth.uid() and status = 'active');
$$;

revoke execute on function public.is_platform_admin() from public, anon;
grant execute on function public.is_platform_admin() to authenticated;

create or replace function public.approve_school(p_school_id uuid, p_decision text, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  updated_school public.schools;
begin
  if not public.is_platform_admin() then
    raise exception 'Platform administrator required';
  end if;
  if p_decision not in ('approved','rejected','suspended') then
    raise exception 'Unsupported school decision';
  end if;
  update public.schools
  set approval_status = p_decision,
      approved_at = case when p_decision = 'approved' then now() else null end,
      approved_by = case when p_decision = 'approved' then auth.uid() else null end,
      rejection_reason = case when p_decision = 'rejected' then nullif(trim(p_reason), '') else null end
  where id = p_school_id
  returning * into updated_school;
  if updated_school.id is null then
    raise exception 'School not found';
  end if;
  return jsonb_build_object('id', updated_school.id, 'status', updated_school.approval_status, 'name', updated_school.name);
end;
$$;

revoke all on function public.approve_school(uuid, text, text) from public, anon;
grant execute on function public.approve_school(uuid, text, text) to authenticated;

